    {
        ++g_inited;
        Interaction* interaction = new Interaction(m_pWorld);
        delete g_interaction; g_interaction = interaction;
        const char* bankName = "PARTICLE_MAIN";
        std::strcpy(g_bank, bankName);
    }
};
int main()
{
    World w = { 3 };
